//! Parser for human readable durations such as `2h10min` or `1.5s`.

use std::fmt;
use std::str::Chars;
use std::time::Duration;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    InvalidCharacter(usize),
    NumberExpected(usize),
    UnknownUnit { unit: String, value: u64 },
    NumberOverflow,
    Empty,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidCharacter(offset) => write!(f, "invalid character at {}", offset),
            Error::NumberExpected(offset) => write!(f, "expected number at {}", offset),
            Error::UnknownUnit { unit, value } if unit.is_empty() => write!(
                f,
                "time unit needed, for example {0}sec or {0}ms",
                value
            ),
            Error::UnknownUnit { unit, .. } => write!(
                f,
                "unknown time unit {:?}, supported units: ns, us/µs, ms, sec, min, hours, days, \
                 weeks, months, years (and few variations)",
                unit
            ),
            Error::NumberOverflow => write!(
                f,
                "number is too large or cannot be represented without a lack of precision \
                 (values below 1ns are not supported)"
            ),
            Error::Empty => write!(f, "value was empty"),
        }
    }
}

impl std::error::Error for Error {}

#[derive(Clone, Copy)]
struct Fraction {
    numerator: u64,
    digits: u32,
}

struct Parser<'a> {
    iter: Chars<'a>,
    src: &'a str,
    secs: u64,
    nanos: u64,
}

fn is_unit_char(c: char) -> bool {
    c.is_ascii_alphabetic() || c == 'µ'
}

impl<'a> Parser<'a> {
    fn off(&self) -> usize {
        self.src.len() - self.iter.as_str().len()
    }

    fn parse_first_char(&mut self) -> Result<Option<u64>, Error> {
        let off = self.off();
        for c in self.iter.by_ref() {
            match c {
                '0'..='9' => return Ok(Some(c as u64 - '0' as u64)),
                c if c.is_whitespace() => continue,
                _ => return Err(Error::NumberExpected(off)),
            }
        }
        Ok(None)
    }

    fn add(&mut self, secs: u64, nanos: u64) -> Result<(), Error> {
        let mut nanos = self.nanos.checked_add(nanos).ok_or(Error::NumberOverflow)?;
        let mut secs = secs;
        if nanos >= 1_000_000_000 {
            secs = secs
                .checked_add(nanos / 1_000_000_000)
                .ok_or(Error::NumberOverflow)?;
            nanos %= 1_000_000_000;
        }
        self.secs = self.secs.checked_add(secs).ok_or(Error::NumberOverflow)?;
        self.nanos = nanos;
        Ok(())
    }

    fn parse_unit(
        &mut self,
        n: u64,
        frac: Option<Fraction>,
        start: usize,
        end: usize,
    ) -> Result<(), Error> {
        // (seconds per unit, nanoseconds per unit)
        let (unit_secs, unit_nanos): (u64, u64) = match &self.src[start..end] {
            "nanos" | "nsec" | "ns" => (0, 1),
            "usec" | "us" | "µs" => (0, 1_000),
            "millis" | "msec" | "ms" => (0, 1_000_000),
            "seconds" | "second" | "secs" | "sec" | "s" => (1, 0),
            "minutes" | "minute" | "min" | "mins" | "m" => (60, 0),
            "hours" | "hour" | "hr" | "hrs" | "h" => (3_600, 0),
            "days" | "day" | "d" => (86_400, 0),
            "weeks" | "week" | "w" => (604_800, 0),
            "months" | "month" | "M" => (2_630_016, 0),
            "years" | "year" | "yr" | "yrs" | "y" => (31_557_600, 0),
            unit => {
                return Err(Error::UnknownUnit {
                    unit: unit.to_string(),
                    value: n,
                })
            }
        };
        let secs = n.checked_mul(unit_secs).ok_or(Error::NumberOverflow)?;
        let nanos = n.checked_mul(unit_nanos).ok_or(Error::NumberOverflow)?;
        self.add(secs, nanos)?;
        if let Some(frac) = frac {
            if unit_secs == 0 && unit_nanos == 1 {
                return Err(Error::NumberOverflow);
            }
            let total_unit_nanos = unit_secs
                .checked_mul(1_000_000_000)
                .and_then(|x| x.checked_add(unit_nanos))
                .ok_or(Error::NumberOverflow)?;
            let denom = 10u64
                .checked_pow(frac.digits)
                .ok_or(Error::NumberOverflow)?;
            let scaled = frac
                .numerator
                .checked_mul(total_unit_nanos)
                .ok_or(Error::NumberOverflow)?;
            if scaled % denom != 0 {
                return Err(Error::NumberOverflow);
            }
            let frac_nanos = scaled / denom;
            self.add(frac_nanos / 1_000_000_000, frac_nanos % 1_000_000_000)?;
        }
        Ok(())
    }

    fn parse(mut self) -> Result<Duration, Error> {
        let mut n = self.parse_first_char()?.ok_or(Error::Empty)?;
        'outer: loop {
            let mut frac: Option<Fraction> = None;
            let mut off = self.off();
            'number: while let Some(c) = self.iter.next() {
                match c {
                    '0'..='9' => {
                        n = n
                            .checked_mul(10)
                            .and_then(|x| x.checked_add(c as u64 - '0' as u64))
                            .ok_or(Error::NumberOverflow)?;
                    }
                    c if c.is_whitespace() => {}
                    '.' => {
                        let mut numerator: u64 = 0;
                        let mut digits: u32 = 0;
                        while let Some(c) = self.iter.next() {
                            match c {
                                '0'..='9' => {
                                    numerator = numerator
                                        .checked_mul(10)
                                        .and_then(|x| x.checked_add(c as u64 - '0' as u64))
                                        .ok_or(Error::NumberOverflow)?;
                                    digits += 1;
                                }
                                c if c.is_whitespace() => {}
                                c if is_unit_char(c) => {
                                    if digits == 0 {
                                        return Err(Error::InvalidCharacter(off));
                                    }
                                    frac = Some(Fraction { numerator, digits });
                                    break 'number;
                                }
                                _ => return Err(Error::InvalidCharacter(off)),
                            }
                            off = self.off();
                        }
                        if digits == 0 {
                            return Err(Error::InvalidCharacter(off));
                        }
                        frac = Some(Fraction { numerator, digits });
                        break 'number;
                    }
                    c if is_unit_char(c) => break,
                    _ => return Err(Error::InvalidCharacter(off)),
                }
                off = self.off();
            }
            let start = off;
            let mut off = self.off();
            while let Some(c) = self.iter.next() {
                match c {
                    '0'..='9' => {
                        self.parse_unit(n, frac, start, off)?;
                        n = c as u64 - '0' as u64;
                        continue 'outer;
                    }
                    c if c.is_whitespace() => break,
                    c if is_unit_char(c) => {}
                    _ => return Err(Error::InvalidCharacter(off)),
                }
                off = self.off();
            }
            self.parse_unit(n, frac, start, off)?;
            n = match self.parse_first_char()? {
                Some(n) => n,
                None => return Ok(Duration::new(self.secs, self.nanos as u32)),
            };
        }
    }
}

/// Parse a duration such as `2h10min`, `15days 2min 2s` or `1.5h`.
pub fn parse_duration(s: &str) -> Result<Duration, Error> {
    Parser {
        iter: s.chars(),
        src: s,
        secs: 0,
        nanos: 0,
    }
    .parse()
}
