//! Low level output helpers shared by all modules.

use std::io::Write;
use std::sync::atomic::{AtomicU32, AtomicU64, Ordering};
use std::time::Duration;

static SPEED_FACTOR_BITS: AtomicU32 = AtomicU32::new(0x3f80_0000); // 1.0f32
static INSTANT_SLEEPS_LEFT: AtomicU64 = AtomicU64::new(0);

pub fn init(speed_factor: f32, instant_print_lines: u32) {
    SPEED_FACTOR_BITS.store(speed_factor.to_bits(), Ordering::SeqCst);
    INSTANT_SLEEPS_LEFT.store(instant_print_lines as u64, Ordering::SeqCst);
}

pub fn speed_factor() -> f32 {
    f32::from_bits(SPEED_FACTOR_BITS.load(Ordering::SeqCst))
}

#[repr(C)]
#[derive(Default)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn isatty(fd: i32) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

fn size_of_fd(fd: i32) -> Option<(u16, u16)> {
    unsafe {
        if isatty(fd) != 1 {
            return None;
        }
        let mut ws = WinSize::default();
        if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) == -1 {
            return None;
        }
        if ws.ws_row > 0 && ws.ws_col > 0 {
            Some((ws.ws_col, ws.ws_row))
        } else {
            None
        }
    }
}

/// Size of the terminal attached to stdout, stderr or stdin (in that order).
pub fn terminal_size() -> Option<(u16, u16)> {
    size_of_fd(1).or_else(|| size_of_fd(2)).or_else(|| size_of_fd(0))
}

/// Width used for wrapping the `--help` output.
pub fn help_width() -> Option<usize> {
    match terminal_size() {
        Some((w, _)) => Some(w as usize),
        None => std::env::var("COLUMNS").ok().and_then(|v| v.parse::<usize>().ok()),
    }
}

/// Sleep for the given amount of milliseconds, scaled by the global speed factor.
pub fn csleep(length: u64) {
    let left = INSTANT_SLEEPS_LEFT.load(Ordering::SeqCst);
    let millis = if left > 0 {
        INSTANT_SLEEPS_LEFT.store(left - 1, Ordering::SeqCst);
        0
    } else {
        (length as f64 / speed_factor() as f64) as u64
    };
    crate::exit::check_signal();
    std::thread::sleep(Duration::from_millis(millis) + Duration::from_micros(1000));
    crate::exit::check_signal();
}

/// Print every character of `s` with `delay` milliseconds in between.
pub fn dprint<S: AsRef<str>>(s: S, delay: u64) {
    for c in s.as_ref().chars() {
        let mut buf = [0u8; 4];
        print(c.encode_utf8(&mut buf));
        csleep(delay);
    }
}

/// Print the given text to stdout and flush it immediately.
pub fn print<S: AsRef<str>>(s: S) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(s.as_ref().as_bytes()).unwrap();
    lock.flush().unwrap();
}

pub fn newline() {
    print("\r\n");
}

pub fn erase_line() {
    print("\x1b[2K\x1b[0G");
}

pub fn cursor_up(n: u64) {
    print(format!("\x1b[{}A", n));
}

pub fn cursor_left(n: u64) {
    print(format!("\x1b[{}D", n));
}

pub fn get_terminal_width() -> usize {
    match terminal_size() {
        Some((w, _)) => w as usize,
        None => panic!("Couldn't get terminal width. Is an interactive terminal attached?"),
    }
}
EOF
