pub fn dprint<S: AsRef<str>>(s: S, delay: u64) {
    for c in s.as_ref().chars() {
        let mut buf = [0u8; 4];
        print(c.encode_utf8(&mut buf));
        csleep(delay);
    }
}

/// Print the given text to stdout and flush it immediately.
pub fn print<S: AsRef<str>>(s: S) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(s.as_ref().as_bytes()).unwrap();
    lock.flush().unwrap();
}

