    print(format!("\x1b[{}A", n));
}

pub fn cursor_left(n: u64) {
    print(format!("\x1b[{}D", n));
}

pub fn get_terminal_width() -> usize {
    match terminal_size() {
        Some((w, _)) => w as usize,
        None => panic!("Couldn't get terminal width. Is an interactive terminal attached?"),
    }
}
