//! Best effort attempt at keeping the machine awake (`--inhibit`).
//!
//! On Linux this talks to the session bus. When no session bus is reachable we
//! print a warning just like the reference implementation and carry on.

use std::os::unix::net::UnixStream;

extern "C" {
    fn getuid() -> u32;
}

fn session_bus_path() -> Result<String, String> {
    match std::env::var("DBUS_SESSION_BUS_ADDRESS") {
        Ok(addr) => {
            for part in addr.split(';') {
                if let Some(rest) = part.strip_prefix("unix:") {
                    for kv in rest.split(',') {
                        if let Some(path) = kv.strip_prefix("path=") {
                            return Ok(path.to_string());
                        }
                    }
                }
            }
            Err("address error: Invalid address. See https://dbus.freedesktop.org/doc/dbus-specification.html#addresses".to_string())
        }
        Err(_) => {
            let runtime_dir = std::env::var("XDG_RUNTIME_DIR")
                .unwrap_or_else(|_| format!("/run/user/{}", unsafe { getuid() }));
            Ok(format!("{}/bus", runtime_dir))
        }
    }
}

pub fn inhibit() {
    let result = session_bus_path().and_then(|path| {
        UnixStream::connect(&path)
            .map(|_| ())
            .map_err(|e| format!("I/O error: {}", e))
    });
    if let Err(e) = result {
        println!("WARN: failed to set up idle inhibition: system: {}", e);
    }
}
