//! A small, fast pseudo random number generator (xoshiro256**).

use std::cell::RefCell;
use std::time::{SystemTime, UNIX_EPOCH};

pub struct Rng {
    s: [u64; 4],
}

fn splitmix(state: &mut u64) -> u64 {
    *state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
    let mut z = *state;
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

impl Rng {
    pub fn from_entropy() -> Rng {
        let mut seed: u64 = 0;
        if let Ok(bytes) = std::fs::read("/proc/sys/kernel/random/uuid") {
            for b in bytes {
                seed = seed.rotate_left(5) ^ b as u64;
                seed = seed.wrapping_mul(0x100_0000_01B3);
            }
        }
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0);
        seed ^= now ^ ((std::process::id() as u64) << 32);
        let mut st = seed;
        Rng {
            s: [
                splitmix(&mut st),
                splitmix(&mut st),
                splitmix(&mut st),
                splitmix(&mut st),
            ],
        }
    }

    pub fn next_u64(&mut self) -> u64 {
        let result = self.s[1].wrapping_mul(5).rotate_left(7).wrapping_mul(9);
        let t = self.s[1] << 17;
        self.s[2] ^= self.s[0];
        self.s[3] ^= self.s[1];
        self.s[1] ^= self.s[2];
        self.s[0] ^= self.s[3];
        self.s[2] ^= t;
        self.s[3] = self.s[3].rotate_left(45);
        result
    }

    /// Uniform integer in `[0, n)`.
    pub fn below(&mut self, n: u64) -> u64 {
        if n == 0 {
            return 0;
        }
        let zone = u64::MAX - (u64::MAX % n);
        loop {
            let v = self.next_u64();
            if v < zone {
                return v % n;
            }
        }
    }

    /// Uniform float in `[0, 1)`.
    pub fn f64(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 * (1.0 / (1u64 << 53) as f64)
    }
}

thread_local! {
    static RNG: RefCell<Rng> = RefCell::new(Rng::from_entropy());
}

pub fn with<T>(f: impl FnOnce(&mut Rng) -> T) -> T {
    RNG.with(|r| f(&mut r.borrow_mut()))
}

/// Uniform integer in the half open range `[lo, hi)`.
pub fn range(lo: u64, hi: u64) -> u64 {
    if hi <= lo {
        return lo;
    }
    with(|r| lo + r.below(hi - lo))
}

/// Uniform integer in the closed range `[lo, hi]`.
pub fn range_incl(lo: u64, hi: u64) -> u64 {
    if hi < lo {
        return lo;
    }
    if lo == 0 && hi == u64::MAX {
        return with(|r| r.next_u64());
    }
    with(|r| lo + r.below(hi - lo + 1))
}

/// Uniform signed integer in the half open range `[lo, hi)`.
pub fn range_i64(lo: i64, hi: i64) -> i64 {
    if hi <= lo {
        return lo;
    }
    let span = (hi as i128 - lo as i128) as u64;
    with(|r| (lo as i128 + r.below(span) as i128) as i64)
}

/// Uniform float in `[lo, hi)`.
pub fn range_f64(lo: f64, hi: f64) -> f64 {
    with(|r| lo + r.f64() * (hi - lo))
}

/// Returns true with probability `p`.
pub fn bool(p: f64) -> bool {
    with(|r| r.f64() < p)
}

pub fn choose<T>(items: &[T]) -> &T {
    let idx = range(0, items.len() as u64) as usize;
    &items[idx]
}

pub fn shuffle<T>(items: &mut [T]) {
    with(|r| {
        for i in (1..items.len()).rev() {
            let j = r.below(i as u64 + 1) as usize;
            items.swap(i, j);
        }
    })
}

/// Pick `n` distinct elements (in random order).
pub fn sample<T: Clone>(items: &[T], n: usize) -> Vec<T> {
    let mut idx: Vec<usize> = (0..items.len()).collect();
    shuffle(&mut idx);
    idx.into_iter().take(n).map(|i| items[i].clone()).collect()
}
