//! Tiny replacement for the `terminal_size` crate, providing just what clap needs.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn isatty(fd: i32) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

/// Returns the size of the terminal attached to the given file descriptor.
pub fn terminal_size_of_fd(fd: i32) -> Option<(Width, Height)> {
    unsafe {
        if isatty(fd) != 1 {
            return None;
        }
        let mut ws = WinSize::default();
        if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) == -1 {
            return None;
        }
        if ws.ws_row > 0 && ws.ws_col > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}

/// Returns the size of the terminal, checking stdout, stderr and stdin in that order.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of_fd(1)
        .or_else(|| terminal_size_of_fd(2))
        .or_else(|| terminal_size_of_fd(0))
}
