//! Helpers that generate random but plausible looking values.

use crate::rng;

/// Standard normal distributed value (Box-Muller).
pub fn normal() -> f64 {
    loop {
        let u1 = rng::range_f64(0.0, 1.0);
        let u2 = rng::range_f64(0.0, 1.0);
        if u1 > 1e-300 {
            return (-2.0 * u1.ln()).sqrt() * (2.0 * std::f64::consts::PI * u2).cos();
        }
    }
}

/// Chi squared distributed value with one degree of freedom.
pub fn chi_squared_1() -> f64 {
    let z = normal();
    z * z
}

/// Exponentially distributed value with the given mean.
pub fn exponential(mean: f64) -> f64 {
    let u = 1.0 - rng::range_f64(0.0, 1.0);
    -u.ln() * mean
}

/// Version string such as `0.12.3` as used by most package managers.
pub fn gen_package_version() -> String {
    format!(
        "{:.0}.{:.0}.{:.0}",
        exponential(0.5),
        10.0 * chi_squared_1(),
        10.0 * chi_squared_1()
    )
}

/// Random lowercase hex string of the given length.
pub fn gen_hex_string(len: usize) -> String {
    const HEX: &[u8] = b"0123456789abcdef";
    (0..len)
        .map(|_| HEX[rng::range(0, 16) as usize] as char)
        .collect()
}
