//! Pretend to boot a system.

use crate::args::AppConfig;
use crate::data;
use crate::exit::should_exit;
use crate::io::{csleep, dprint, newline};
use crate::rng;

pub fn run(_appconfig: &AppConfig) {
    let num_lines = rng::range(50, 200);
    let mut burst_mode = false;
    let mut count_burst_lines = 0;

    for _ in 1..num_lines {
        let choice = *rng::choose(data::bootlog());
        let mut line_sleep_length = rng::range(10, 1000);
        let mut char_sleep_length = 5;
        let burst_lines = rng::range(10, 50);

        if burst_mode && count_burst_lines < burst_lines {
            line_sleep_length = 30;
            char_sleep_length = 0;
            count_burst_lines += 1;
        } else if count_burst_lines == burst_lines {
            burst_mode = false;
            count_burst_lines = 0;
        } else if !burst_mode {
            burst_mode = rng::bool(1.0 / 20.0);
        }

        let is_error = rng::bool(0.01);
        if is_error {
            dprint(format!("\x1b[31mERROR: {}\x1b[0m", choice), 10);
        } else {
            let has_bold_word = rng::bool(0.1);
            if has_bold_word {
                let mut words: Vec<String> = choice.split_whitespace().map(String::from).collect();
                if !words.is_empty() {
                    words[0] = format!("\x1b[1m{}\x1b[0m", words[0]);
                }
                dprint(words.join(" "), char_sleep_length);
            } else {
                dprint(choice, char_sleep_length);
            }
        }

        newline();
        csleep(line_sleep_length);

        if should_exit() {
            return;
        }
    }
}
