    ("XZKERN", "arch/ARCH/boot/compressed/vmlinux.bin.xz"),
    ("ZOFFSET", "arch/ARCH/boot/zoffset.h"),
];

/// (command, extension, weight)
const COMMANDS: &[(&str, &str, f64)] = &[
    ("CC", ".o", 0.5520),
    ("AR", ".o", 0.2720),
    ("CHK", ".h", 0.0303),
    ("WRAP", ".h", 0.0303),
    ("UPD", ".h", 0.0302),
    ("HOSTCC", ".o", 0.0295),
    ("AS", ".o", 0.0293),
    ("SYSHDR", ".h", 0.0034),
    ("SYSTBL", ".h", 0.0033),
];
const SPECIAL_WEIGHT: f64 = 0.0198;

fn replace_arch(path: &str, arch: &str) -> String {
    if let Some(rest) = path.strip_prefix("arch/") {
        if let Some(idx) = rest.find('/') {
            return format!("arch/{}{}", arch, &rest[idx..]);
        }
    }
    path.to_string()
}

fn gen_line(arch: &str) -> String {
    let total: f64 = COMMANDS.iter().map(|c| c.2).sum::<f64>() + SPECIAL_WEIGHT;
    let mut r = rng::range_f64(0.0, total);
    if r < SPECIAL_WEIGHT {
        let (cmd, path) = rng::choose(SPECIAL_LINES);
        return format!("  {:<8}{}", cmd, path.replace("ARCH", arch));
