    r -= SPECIAL_WEIGHT;
    let mut chosen = &COMMANDS[0];
    for command in COMMANDS {
        if r < command.2 {
            chosen = command;
            break;
        }
        r -= command.2;
    }
    let cfile = *rng::choose(data::cfiles());
    let file = replace_arch(&cfile.replace(".c", chosen.1), arch);
    format!("  {:<8}{}", chosen.0, file)
}

