    let arch = *rng::choose(ARCHES);
    let num_lines = rng::range(50, 500);

    for _ in 1..num_lines {
        print(gen_line(arch));
        newline();
        csleep(rng::range(10, 1000));
        if should_exit() {
            return;
        }
    }

    let setup = rng::range(10_000, 1_000_000);
    let padded = rng::range(setup, 1_100_000);
    let system = rng::range(300, 3000);
    let crc = rng::range(0x1000_0000, 0x1_0000_0000);

    print(format!("BUILD   arch/{}/boot/bzImage", arch));
    newline();
    newline();
    print(format!(
        "Setup is {} bytes (padded to {} bytes).",
        setup, padded
    ));
    newline();
    print(format!("System is {} kB", system));
    newline();
    print(format!("CRC {:x}", crc));
    newline();
    print(format!("Kernel: arch/{}/boot/bzImage is ready (#1)", arch));
    newline();
    newline();
}
