//! Pretend to generate an initramfs with mkinitcpio.

use crate::args::AppConfig;
use crate::data;
use crate::exit::should_exit;
use crate::io::{csleep, newline, print};
use crate::rng;

const REQUIRED_HOOKS: &[&str] = &[
    "base",
    "udev",
    "autodetect",
    "modconf",
    "block",
    "fsck",
    "filesystems",
];

/// All hooks in the order in which they are run. Hooks that are not in
/// `REQUIRED_HOOKS` are only sometimes included.
const ALL_HOOKS: &[&str] = &[
    "base",
    "udev",
    "usr",
    "resume",
    "autodetect",
    "modconf",
    "block",
    "net",
    "mdadm",
    "mdadm_udev",
    "keyboard",
    "keymap",
    "consolefont",
    "encrypt",
    "lvm2",
    "fsck",
    "filesystems",
];

const COMPRESSIONS: &[&str] = &["gzip", "bzip2", "lzma", "xz", "lzop", "lz4", "zstd"];

fn msg1(msg: &str) {
    print(format!("\x1b[1;32m==> \x1b[0m\x1b[1m{}\x1b[0m", msg));
    newline();
}

fn msg2(msg: &str) {
    print(format!("\x1b[1;34m  -> \x1b[0m\x1b[1m{}\x1b[0m", msg));
    newline();
}

fn warn(msg: &str) {
    print(format!("\x1b[1;33m==> WARNING: \x1b[0m\x1b[1m{}\x1b[0m", msg));
    newline();
}

/// Returns false if genact should exit.
fn build(hooks: &[&str], preset: &str, mode: &str, zip: &str, os_release: &str) -> bool {
    msg1(&format!(
        "Building image from preset: /etc/mkinitcpio.d/{}.preset: '{}'",
        preset, mode
    ));
    let image = if mode == "default" {
        format!("/boot/initramfs-{}.img", preset)
    } else {
        format!("/boot/initramfs-{}-{}.img", preset, mode)
    };
    msg2(&format!(
        "-k /boot/vmlinuz-{} -c /etc/mkinitcpio.conf -g {}",
        preset, image
    ));
    msg1(&format!("Starting build: {}", os_release));

    for hook in hooks {
        msg2(&format!("Running build hook: [{}]", hook));
        csleep(rng::range(50, 1000));

        if mode == "fallback" && *hook == "block" {
            let num_warnings = rng::range(0, 5) as usize;
            for module in rng::sample(data::firmware(), num_warnings) {
                warn(&format!("Possibly missing firmware for module: {}", module));
            }
        }

        if should_exit() {
            return false;
        }
    }

    msg1("Generating module dependencies");
    csleep(rng::range(100, 1000));

    msg1(&format!(
        "Creating {}-compressed initcpio image: {}",
        zip, image
    ));
    csleep(rng::range(500, 2500));

    msg1("Image generation successful");
    !should_exit()
}

pub fn run(_appconfig: &AppConfig) {
    let hooks: Vec<&str> = ALL_HOOKS
        .iter()
        .copied()
        .filter(|h| REQUIRED_HOOKS.contains(h) || rng::bool(0.3))
        .collect();

    let preset = "linux";
    let zip = *rng::choose(COMPRESSIONS);
    let os_release = *rng::choose(data::os_releases());

    if !build(&hooks, preset, "default", zip, os_release) {
        return;
    }
    build(&hooks, preset, "fallback", zip, os_release);
}
