//! Pretend to download a couple of files, wget style.

use crate::args::AppConfig;
use crate::data;
use crate::exit::should_exit;
use crate::generators::{format_bytes, with_extension};
use crate::io::{csleep, dprint, erase_line, get_terminal_width, print, newline};
use crate::rng;

const MIB: f64 = 1024.0 * 1024.0;

fn basename(path: &str) -> &str {
    path.rsplit('/').next().unwrap_or(path)
}

struct Layout {
    name_width: usize,
    bar_width: usize,
}

fn layout(width: usize) -> Option<Layout> {
    let name_width = ((width as f64 / 3.0).round() as i64 - 10).max(0);
    let bar_width = width as i64 - 47 - name_width;
    if bar_width < 0 {
        return None;
    }
    Some(Layout {
        name_width: name_width as usize,
        bar_width: bar_width as usize,
    })
}

fn render_bar(width: usize, downloaded: f64, total: f64) -> String {
    if downloaded <= 0.0 {
        return " ".repeat(width);
    }
    if downloaded >= total {
        return "=".repeat(width);
    }
    let filled = (((downloaded / total) * width as f64) as usize).min(width.saturating_sub(1));
    if width == 0 {
        return String::new();
    }
    format!(
        "{}█{}",
        "=".repeat(filled),
        " ".repeat(width - filled - 1)
    )
}

fn render_line(
    layout: &Layout,
    name: &str,
    downloaded: f64,
    total: f64,
    chunk: f64,
    eta: u64,
) -> String {
