/// A julia style progress bar with 41 cells.
fn bar(fraction: f64) -> String {
    const WIDTH: usize = 41;
    if fraction <= 0.0 {
        return " ".repeat(WIDTH);
    }
    let filled = ((fraction * WIDTH as f64) as usize).min(WIDTH - 1);
    format!("{}█{}", "=".repeat(filled), " ".repeat(WIDTH - filled - 1))
}

