fn packages() -> &'static [Package] {
    static CELL: OnceLock<Vec<Package>> = OnceLock::new();
    CELL.get_or_init(|| {
        include_str!("../../data/julia.txt")
            .lines()
            .filter_map(|line| {
                let mut parts = line.split(' ');
                let name = parts.next()?;
                let uuid = parts.next()?;
                let version = parts.next()?;
                Some(Package {
                    name,
                    uuid,
                    version,
                    older: parts.collect(),
                })
            })
            .collect()
    })
}

const BANNER: &str = "               \x1b[1;32m_\x1b[0m\r
   \x1b[1;34m_\x1b[0m       _ \x1b[1;31m_\x1b[0m\x1b[1;32m(_)\x1b[0m\x1b[1;35m_\x1b[0m     |  Documentation: https://docs.julialang.org\r
  \x1b[1;34m(_)\x1b[0m     | \x1b[1;31m(_)\x1b[0m \x1b[1;35m(_)\x1b[0m    |\r
   _ _   _| |_  __ _   |  Type \"?\" for help, \"]?\" for Pkg help.\r
  | | | | | | |/ _` |  |\r
  | | |_| | | | (_| |  |  Version 1.7.3 (2022-05-06)\r
 _/ |\\__'_|_|_|\\__'_|  |  Fedora 35 build\r
|__/                   |\r
";

fn green(s: &str) -> String {
    format!("\x1b[1;32m{}\x1b[0m", s)
}

fn cyan(s: &str) -> String {
    format!("\x1b[1;36m{}\x1b[0m", s)
}

/// A julia style progress bar with 41 cells.
fn bar(fraction: f64) -> String {
    const WIDTH: usize = 41;
    if fraction <= 0.0 {
        return " ".repeat(WIDTH);
    }
    let filled = ((fraction * WIDTH as f64) as usize).min(WIDTH - 1);
    format!("{}█{}", "=".repeat(filled), " ".repeat(WIDTH - filled - 1))
}

fn replace_line() {
    cursor_up(1);
    erase_line();
}

fn gen_uuid() -> String {
    format!(
        "{}-{}-{}-{}-{}",
        gen_hex_string(8),
        gen_hex_string(4),
        gen_hex_string(4),
        gen_hex_string(4),
        gen_hex_string(12)
    )
}

pub fn run(_appconfig: &AppConfig) {
    let all = packages();
    let start = Instant::now();

    let env = if rng::bool(0.3) {
        "@v1.7".to_string()
    } else {
        rng::choose(all).name.to_string()
    };
    let project_dir = if env == "@v1.7" {
        "~/.julia/environments/v1.7".to_string()
    } else {
        format!("~/Documents/code/julia/projects/{}.jl", env)
    };
    let prompt = format!("\x1b[1;34m({}) pkg>\x1b[0m ", env);

    print(BANNER);
    csleep(150);
    newline();
    print(format!("{} ", green("julia>")));
    csleep(rng::range(1000, 3000));
    erase_line();
    print(&prompt);
    dprint("update", rng::range(100, 1000));
    newline();
    csleep(rng::range(1000, 4000));

    print(format!("{} registry at `~/.julia/registries/General.toml`", green("    Updating")));
    newline();
    csleep(rng::range(1000, 5000));
    print(format!("{} package versions...", green("   Resolving")));
    newline();
    csleep(rng::range(500, 2000));
    if should_exit() {
        return;
    }

    // Install packages.
    let num_packages = rng::range(10, 150) as usize;
    let chosen: Vec<&Package> = rng::sample(&all.iter().collect::<Vec<_>>(), num_packages);
    let width = chosen.iter().map(|p| p.name.chars().count()).max().unwrap_or(0) + 1;
    for package in &chosen {
        let dashes = "─".repeat(width - package.name.chars().count());
        let line = |stage: &str| format!("{} {} {} v{}", green(stage), package.name, dashes, package.version);
        if rng::bool(0.1) {
            print(line("  Installing"));
            newline();
            csleep(rng::range(500, 2000));
            replace_line();
        }
        print(line("   Installed"));
        newline();
        csleep(rng::range(10, 1000));
        if should_exit() {
            return;
        }
    }

    // Download artifacts.
    let num_artifacts = rng::range(1, 10) as usize;
    let artifacts: Vec<&Package> = rng::sample(&all.iter().collect::<Vec<_>>(), num_artifacts);
    for artifact in &artifacts {
        print(format!("{} artifact: {}", green(" Downloading"), artifact.name));
        newline();
        let mut percent: f64 = 0.0;
        loop {
            print(format!("{} [{}] {:.2}%", cyan("    Downloading"), bar(percent / 100.0), percent));
            newline();
            if percent >= 100.0 {
                break;
            }
            csleep(rng::range(10, 500));
            let mut next = percent + rng::range_f64(0.0, 5.0);
            if next > 100.0 {
                next = percent + (100.0 - percent) * rng::range_f64(0.3, 0.9);
            }
            if 100.0 - next < 0.005 {
                next = 100.0;
            }
            percent = next;
            replace_line();
            if should_exit() {
                return;
            }
        }
        replace_line();
        replace_line();
        print(format!("{} artifact: {}", green("  Downloaded"), artifact.name));
        newline();
        csleep(rng::range(10, 500));
    }

    // Report what changed.
    for file in ["Project.toml", "Manifest.toml"] {
        print(format!("{} `{}/{}`", green("    Updating"), project_dir, file));
        newline();
        csleep(rng::range(50, 500));
    }
    for package in &chosen {
        let roll = rng::range_f64(0.0, 1.0);
        let change = if roll < 0.045 {
            format!("\x1b[38;5;9m- {} v{}\x1b[0m", package.name, package.version)
        } else if !package.older.is_empty() && rng::bool(0.75) {
            let old = rng::choose(&package.older);
            format!(
                "\x1b[38;5;11m↑ {} v{} ⇒ v{}\x1b[0m",
                package.name, old, package.version
            )
        } else {
            format!("\x1b[38;5;10m+ {} v{}\x1b[0m", package.name, package.version)
        };
        print(format!("  \x1b[38;5;8m[{}]\x1b[0m {}", package.uuid, change));
        newline();
        csleep(rng::range(20, 100));
    }

    // Build artifacts.
    let build_width = artifacts.iter().map(|p| p.name.chars().count()).max().unwrap_or(0) + 1;
    let total = artifacts.len();
    print(format!("{} [{}] 0/{}", cyan("  Progress"), bar(0.0), total));
    newline();
    for (i, artifact) in artifacts.iter().enumerate() {
        csleep(rng::range(1000, 5000));
        replace_line();
        print(format!(
            "{} {} {}→ `~/.julia/scratchspaces/{}/{}/build.log`",
            green("    Building"),
            artifact.name,
            "─".repeat(build_width - artifact.name.chars().count()),
            gen_uuid(),
            gen_hex_string(40)
        ));
        newline();
        print(format!(
            "{} [{}] {}/{}",
            cyan("  Progress"),
            bar((i + 1) as f64 / total as f64),
            i + 1,
            total
        ));
        newline();
        if should_exit() {
            return;
        }
    }

    // Precompile.
    replace_line();
    print(format!("{} project...", green("Precompiling")));
    newline();
    let precompile_start = Instant::now();
    let total = chosen.len();
    print(format!("{} [{}] 0/{}", cyan("  Progress"), bar(0.0), total));
    newline();
    for i in 1..=total {
        csleep(rng::range(100, 2000));
        replace_line();
        print(format!(
            "{} [{}] {}/{}",
            cyan("  Progress"),
            bar(i as f64 / total as f64),
            i,
            total
        ));
        newline();
        if should_exit() {
            return;
        }
    }
    replace_line();
    print(format!(
        "  {} dependencies successfully precompiled in {} seconds ({} already precompiled)",
        total,
        precompile_start.elapsed().as_secs(),
        rng::range(10, 500)
    ));
    newline();

    // Garbage collection.
    if rng::bool(0.3) {
        print(format!(
            "{} We haven't cleaned this depot up for a bit, running Pkg.gc()...",
            cyan("[ Info:")
        ));
        newline();
        csleep(rng::range(500, 2000));
        print(format!("{} manifest files: {} found", green("      Active"), rng::range(1, 10)));
        newline();
        print(format!("{} artifact files: {} found", green("      Active"), rng::range(10, 200)));
        newline();
        print(format!("{} scratchspaces: {} found", green("      Active"), rng::range(10, 20)));
        newline();
        csleep(rng::range(500, 2000));
        print(format!(
            "{} {} package installations ({:.3} MiB)",
            green("     Deleted"),
            rng::range(2, 100),
            rng::range_f64(10.0, 250.0)
        ));
        newline();
        print(format!(
            "{} {} artifact installations ({:.3} MiB)",
            green("     Deleted"),
            rng::range(2, 10),
            rng::range_f64(10.0, 250.0)
        ));
        newline();
        print(format!(
            "{} {} scratchspaces ({:.3} byte)",
            green("     Deleted"),
            rng::range(2, 10),
            rng::range_f64(10.0, 1000.0)
        ));
        newline();
    }

    newline();
    print(&prompt);
    csleep(rng::range(1000, 5000));
    erase_line();
    print(format!("{} ", green("julia>")));
    csleep(rng::range(1000, 4000));
    newline();
    let _ = start;
}
