];
const SPINNER: [char; 4] = ['|', '/', '-', '\\'];
const HEX: &[u8] = b"0123456789abcdef";

pub fn run(_appconfig: &AppConfig) {
    let num_hashes = rng::range(2, 10) as usize;
    let passwords: Vec<String> = (0..num_hashes)
        .map(|_| {
            format!(
                "{}{:02}",
                rng::pick(data::first_names()).to_lowercase(),
                rng::range(0, 100)
            )
        })
        .collect();
    let hashes: Vec<String> = passwords.iter().map(|p| sha256_hex(p.as_bytes())).collect();

    print("=> Hashes to decrypt");
    newline();
    for hash in &hashes {
        print(format!("  {}", hash));
        newline();
    }
    newline();

    for frame in 0..RAINBOW.len() {
        let mut bar = String::new();
        for (i, color) in RAINBOW.iter().enumerate() {
            let c = if i < frame {
                '='
            } else if i == frame {
                SPINNER[frame % SPINNER.len()]
            } else {
                ' '
            };
            bar.push_str(&format!("\x1b[38;5;{}m{}\x1b[0m", color, c));
        }
        print(format!("\r=> Extracting Rainbow Table [{}]", bar));
        csleep(rng::range(100, 500));
        if should_exit() {
            return;
        }
    }
    newline();
    print("=> Begin matching");
    newline();

    let mut found: Vec<usize> = vec![0; num_hashes];
    let mut first = true;
    loop {
        if !first {
            cursor_up(num_hashes as u64);
        }
        first = false;
        for (hash, pos) in hashes.iter().zip(found.iter_mut()) {
            let target = hash.as_bytes();
            let mut rest = String::new();
            while *pos < target.len() {
                let guess = HEX[rng::range(0, 16) as usize];
                if guess == target[*pos] {
                    *pos += 1;
                } else {
                    rest.push(guess as char);
                    rest.push_str(&gen_hex_string(target.len() - *pos - 1));
                    break;
                }
            }
            print(format!(
                "\r :: \x1b[32m{}\x1b[0m\x1b[31m{}\x1b[0m ::",
                &hash[..*pos],
                rest
            ));
            newline();
        }
        if found.iter().all(|&p| p >= 64) {
            break;
        }
        csleep(10);
        if should_exit() {
            return;
        }
    }

    print("=> Match found");
    newline();
    for (hash, password) in hashes.iter().zip(passwords.iter()) {
        print(format!("  {}:\x1b[1m{}\x1b[0m", hash, password));
        newline();
    }
    csleep(1000);
}
