//! Pretend to install python packages with uv.

use std::time::Instant;

use crate::args::AppConfig;
use crate::data;
use crate::exit::should_exit;
use crate::generators::{format_bytes, gen_package_version};
use crate::io::{csleep, cursor_up, erase_line, newline, print};
use crate::rng;

const SPINNER: [char; 10] = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];
const SLOTS: usize = 20;
const BAR_WIDTH: usize = 30;

fn dim(s: &str) -> String {
    format!("\x1b[2m{}\x1b[0m", s)
}

fn spaced_bytes(bytes: f64) -> String {
    let s = format_bytes(bytes);
    let idx = s.find(|c: char| c.is_ascii_alphabetic()).unwrap_or(s.len());
    format!("{} {}", &s[..idx], &s[idx..])
}

fn elapsed_ms(start: &Instant) -> String {
    format!("{:.2}ms", start.elapsed().as_secs_f64() * 1000.0)
}

struct Download {
    name: &'static str,
    total: f64,
    done: f64,
    speed: f64,
}

pub fn run(_appconfig: &AppConfig) {
    print(format!("Using CPython 3.{}.{}", rng::range(8, 14), rng::range(0, 20)));
    newline();
    print("Creating virtualenv at: .venv");
    newline();
    csleep(rng::range(100, 500));

    // Resolve
    let start = Instant::now();
    let num_resolved = rng::range(20, 250) as usize;
    let resolved = rng::sample(data::packages(), num_resolved);
    for (i, package) in resolved.iter().enumerate() {
        erase_line();
        print(format!("{} {}=={}", SPINNER[i % SPINNER.len()], package, gen_package_version()));
        csleep(rng::range(5, 50));
        if should_exit() {
            return;
        }
    }
    erase_line();
    print(dim(&format!("Resolved {} packages in {}", num_resolved, elapsed_ms(&start))));

    // Prepare
    let start = Instant::now();
    let num_prepared = rng::range(num_resolved as u64 / 2, num_resolved as u64 + 1) as usize;
    for i in 1..=num_prepared {
        erase_line();
        print(dim(&format!(
            "{} Preparing packages... ({}/{})",
            SPINNER[i % SPINNER.len()],
            i,
            num_prepared
        )));
        csleep(rng::range(5, 50));
        if should_exit() {
            return;
        }
    }
    erase_line();
    print(dim(&format!("Prepared {} packages in {}", num_prepared, elapsed_ms(&start))));
    newline();

    // Download
    let mut queue: Vec<Download> = resolved
        .iter()
        .take(num_prepared)
        .map(|name| {
            let total = rng::range_f64(100.0 * 1024.0, 20.0 * 1024.0 * 1024.0);
            Download {
                name,
                total,
                done: 0.0,
                speed: total / rng::range_f64(3.0, 15.0),
            }
        })
        .collect();
    queue.reverse();
    let mut active: Vec<Download> = Vec::new();
    for _ in 0..=SLOTS {
        newline();
    }
    loop {
        while active.len() < SLOTS {
            match queue.pop() {
                Some(d) => active.push(d),
                None => break,
            }
        }
        cursor_up(SLOTS as u64);
        for slot in 0..SLOTS {
            erase_line();
            if let Some(d) = active.get(slot) {
                let filled = ((d.done / d.total) * BAR_WIDTH as f64) as usize;
                let filled = filled.min(BAR_WIDTH);
                print(format!(
                    "{}{}\x1b[32m{}{}\x1b[0m  {:>10}/{:<11}",
                    dim(d.name),
                    " ".repeat(33usize.saturating_sub(d.name.chars().count())),
                    "-".repeat(filled),
                    " ".repeat(BAR_WIDTH - filled),
                    spaced_bytes(d.done),
                    spaced_bytes(d.total)
                ));
            }
            newline();
        }
        if active.is_empty() && queue.is_empty() {
            break;
        }
        active.retain(|d| d.done < d.total);
        for d in active.iter_mut() {
            d.done = (d.done + d.speed * rng::range_f64(0.5, 1.5)).min(d.total);
        }
        csleep(rng::range(20, 100));
        if should_exit() {
            return;
        }
    }
    for _ in 0..SLOTS {
        cursor_up(1);
        erase_line();
    }

    // Install
    let start = Instant::now();
    for i in 0..=num_prepared {
        let filled = i * BAR_WIDTH / num_prepared.max(1);
        erase_line();
        print(format!(
            "[{}{}] [{}/{}] Installing wheels...",
            "█".repeat(filled),
            "░".repeat(BAR_WIDTH - filled),
            i,
            num_prepared
        ));
        csleep(rng::range(5, 50));
        if should_exit() {
            return;
        }
    }
    erase_line();
    print(dim(&format!("Installed {} packages in {}", num_prepared, elapsed_ms(&start))));
    newline();
}
